调用示例
import lombok.Builder;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;


import org.apache.http.HttpStatus;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpDelete;
import org.apache.http.client.utils.URIBuilder;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.junit.Ignore;


/**
 * 删除文件REST API示例代码
 */
@Slf4j
public class DeleteObjectTest {
    /**
     * 删除文件
     * 如果业务需要批量删除文件，则需要for循环调用deleteObject方法
     *
     * @param storageUrl 云存储url
     * @param param 删除文件接口入参
     * @throws Exception 异常
     */
    public static void deleteObject(String storageUrl, DeleteObjectParam param) throws Exception {
        URIBuilder uriBuilder = new URIBuilder(storageUrl + param.getBucketName() + "/" + param.getObjectName());
        HttpDelete httpDelete = new HttpDelete(uriBuilder.build());
        httpDelete.setHeader("productId", param.getProjectId());
        httpDelete.setHeader("client_id", param.getClientId());
        httpDelete.setHeader("Authorization", "Bearer " + param.getToken());
        CloseableHttpClient httpClient = HttpClients.createDefault();
        CloseableHttpResponse httpResponse = httpClient.execute(httpDelete);
        int statusCode = httpResponse.getStatusLine().getStatusCode();
        if (statusCode == HttpStatus.SC_OK) {
            log.info("Delete success");
        } else {
            log.error("Delete failed, errorCode:{}", statusCode);
        }
    }


    public void client() throws Exception {


        String clientToken = TokenServiceTest.getToken("https://connect-api.cloud.huawei.com/api/", "84903XXXXXX32064",
            "00E5CCADB655891XXXXXXXXXXXX8CDCC83ACF22");
        DeleteObjectParam param = DeleteObjectParam.builder()
            .projectId("73643XXXXXX61998")
            .clientId("84903XXXXXX32064")
            .token(clientToken)
            .bucketName("test-q36q0")
            .objectName("temp/hello.txt")
            .build();
        deleteObject("https://ops-server-drcn.agcstorage.link/v0/", param);
    }


    public static void main(String[] args) throws Exception {
        ConstantsTest.preCheck();
        new DeleteObjectTest().client();
    }


    @Builder
    @Getter
    static class DeleteObjectParam {
        // 项目ID
        String projectId;


        // 客户端ID
        String clientId;


        // clientToken
        String token;


        // 云存储实例名
        String bucketName;


        // 待删除的文件名，需要携带路径
        String objectName;
    }
}
